export default function UserOrders({ orders }) {
  return (
    <div>
      <h3>Your Orders</h3>

      {orders.length === 0 && <p>No orders yet</p>}

      {orders.map((o) => (
        <div key={o.id}>
          <p>Status: {o.status}</p>
          <p>Total: ₹{o.total}</p>
        </div>
      ))}
    </div>
  );
}
